import type { NamedLoggerService } from './logger';

type Position = { line: number; column: number };

export function lineFormatter(position: Position, message: string, filePath: string): string {
    return `${message} (${filePath}:${position.line}:${position.column})`;
}

export interface FileParserLogger {
    filePath: string;
    trace(position: Position, message: string): void;
    debug(position: Position, message: string): void;
    info(position: Position, message: string): void;
    warn(position: Position, message: string): void;
    error(position: Position, message: string): void;
}

export class DefaultFileParserLogger {
    constructor(
        private services: NamedLoggerService,
        public filePath: string
    ) {}

    trace(position: Position, message: string): void {
        this.services.logger.trace(this.format(position, message));
    }
    debug(position: Position, message: string): void {
        this.services.logger.debug(this.format(position, message));
    }
    info(position: Position, message: string): void {
        this.services.logger.info(this.format(position, message));
    }
    warn(position: Position, message: string): void {
        this.services.logger.warn(this.format(position, message));
    }
    error(position: Position, message: string): void {
        this.services.logger.error(this.format(position, message));
    }

    format(position: Position, message: string): string {
        return lineFormatter(position, message, this.filePath);
    }
}
