import { ArrayIsArray, JSONStringify, JSONParse, ObjectKeys } from './language';
import { err, ok } from './result';
import type { Result } from './result';

/**
 * Recursively compares two values and indicates if they are equal.
 *
 * @param x first value
 * @param y second value
 * @returns true if x and y are recursively equal to each other; false if not
 */
export function deepEquals<T>(x: T, y: T): boolean {
    if (x === undefined) {
        return y === undefined;
    } else if (x === null) {
        return y === null;
    } else if (y === null) {
        return x === null;
    } else if (ArrayIsArray(x)) {
        if (!ArrayIsArray(y) || x.length !== y.length) {
            return false;
        }

        for (let i = 0; i < x.length; ++i) {
            if (!deepEquals(x[i], y[i])) {
                return false;
            }
        }

        return true;
    } else if (typeof x === 'object') {
        if (typeof y !== 'object') {
            return false;
        }

        const xkeys = Object.keys(x);
        const ykeys = Object.keys(y);
        if (xkeys.length !== ykeys.length) {
            return false;
        }

        for (let i = 0; i < xkeys.length; ++i) {
            const key = xkeys[i];
            if (!deepEquals((x as any)[key], (y as any)[key])) {
                return false;
            }
        }

        return true;
    }
    return x === y;
}

/**
 * A deterministic JSON stringify implementation. Heavily adapted from https://github.com/epoberezkin/fast-json-stable-stringify.
 * This is needed because insertion order for JSON.stringify(object) affects output:
 * JSON.stringify({a: 1, b: 2})
 *      "{"a":1,"b":2}"
 * JSON.stringify({b: 2, a: 1})
 *      "{"b":2,"a":1}"
 * @param data Data to be JSON-stringified.
 * @returns JSON.stringified value with consistent ordering of keys.
 */
export function stableJSONStringify(node: any): string | undefined {
    // This is for Date values.
    if (node && node.toJSON && typeof node.toJSON === 'function') {
        // eslint-disable-next-line no-param-reassign
        node = node.toJSON();
    }
    if (node === undefined) {
        return;
    }
    if (typeof node === 'number') {
        return isFinite(node) ? '' + node : 'null';
    }
    if (typeof node !== 'object') {
        return JSONStringify(node);
    }

    let i;
    let out;
    if (ArrayIsArray(node)) {
        out = '[';
        for (i = 0; i < node.length; i++) {
            if (i) {
                out += ',';
            }
            out += stableJSONStringify(node[i]) || 'null';
        }
        return out + ']';
    }

    if (node === null) {
        return 'null';
    }

    const objKeys = ObjectKeys(node).sort();
    out = '';
    for (i = 0; i < objKeys.length; i++) {
        const key = objKeys[i];
        const value = stableJSONStringify(node[key]);

        if (!value) {
            continue;
        }
        if (out) {
            out += ',';
        }
        out += JSONStringify(key) + ':' + value;
    }
    return '{' + out + '}';
}

/**
 * Converts an arbitrary value to an Error.
 *
 * @param x anything
 * @returns Error corresponding to x
 */
export function toError(x: any): Error {
    if (x instanceof Error) {
        return x;
    }

    return new Error(typeof x === 'string' ? x : JSON.stringify(x));
}

/**
 * Deep copies a JSON object. Only works for non-complex values.
 * No Date or Functions etc.
 */
export function deepCopy<T>(x: T): T | undefined {
    const stringified = JSONStringify(x);
    return stringified ? JSONParse(stringified) : undefined;
}

/**
 * Transforms a ReadableStream in to an AsyncIterable
 *
 * Allows consumption of a ReadableStream using for-await-of syntax.
 * Ensures proper cleanup and error handling for all stream control paths.
 *
 * @param stream the ReadableStream to be transformed
 * @returns Result<AsyncIterable<T>, Error> built from the provided ReadableStream
 */
export function readableStreamToAsyncIterable<T>(
    stream: ReadableStream<T>
): Result<AsyncIterable<T>, Error> {
    if (stream.locked) {
        return err(new Error('ReadableStream is already locked'));
    }

    // If the stream already supports async iteration, just return it
    if (Symbol.asyncIterator in stream) {
        return ok(stream as AsyncIterable<T>);
    }

    const reader = stream.getReader();

    return ok({
        [Symbol.asyncIterator]: () => ({
            next: async () => {
                try {
                    const result = await reader.read();
                    if (result.done) {
                        try {
                            reader.releaseLock();
                        } catch {
                            // intentionally do nothing
                        }
                        return { done: true, value: undefined };
                    }
                    return {
                        done: false,
                        value: result.value,
                    };
                } catch (e) {
                    try {
                        reader.releaseLock();
                    } catch {
                        // intentionally do nothing
                    }
                    throw e;
                }
            },

            return: async (value?: T) => {
                try {
                    await reader.cancel();
                } catch {
                    // intentionally do nothing
                }
                try {
                    reader.releaseLock();
                } catch {
                    // intentionally do nothing
                }
                return { done: true, value };
            },

            throw: async (exception?: any) => {
                try {
                    await reader.cancel();
                } catch {
                    // intentionally do nothing
                }
                try {
                    reader.releaseLock();
                } catch {
                    // intentionally do nothing
                }
                throw exception;
            },
        }),
    });
}
