/**
 * Returns a PromiseLike object that resolves with the specified result.
 *
 * @param result resolved result
 * @returns
 */
export function resolvedPromiseLike<Result>(result: Result | Promise<Result>): PromiseLike<Result> {
    // Don't nest anything promise like
    if (isPromiseLike(result)) {
        return (result as any).then((nextResult: Awaited<Result>) => nextResult);
    }

    return {
        then: <TResult1, TResult2>(
            onFulfilled?: ((result: Result) => TResult1 | Promise<TResult1>) | null | undefined,
            _onRejected?: ((reason: any) => TResult2 | Promise<TResult2>) | null | undefined
        ): PromiseLike<TResult1 | TResult2> => {
            try {
                return resolvedPromiseLike<TResult1>(onFulfilled!(result));
            } catch (e) {
                // We could run this check prior to calling onFulfilled above, but
                // this function has an extremely high call volume with the most likely scenario being that
                // onFulfilled is defined, so it is more efficient to check here.
                if (onFulfilled === undefined) {
                    // assume TResult1 == Result and just pass result down the chain
                    return resolvedPromiseLike(result) as unknown as PromiseLike<TResult1>;
                }
                return rejectedPromiseLike<TResult1>(e);
            }
        },
    };
}

/**
 * Returns a PromiseLike object that rejects with the specified reason.
 *
 * @param reason rejection value
 * @returns PromiseLike that rejects with reason
 */
export function rejectedPromiseLike<Result>(reason: any): PromiseLike<Result> {
    if (isPromiseLike(reason)) {
        return (reason as any).then((nextResult: Awaited<Result>) => nextResult);
    }

    return {
        then: <TResult1, TResult2>(
            _onFulfilled?: ((result: Result) => TResult1 | Promise<TResult1>) | null | undefined,
            onRejected?: ((reason: any) => TResult2 | Promise<TResult2>) | null | undefined
        ): PromiseLike<TResult1 | TResult2> => {
            if (typeof onRejected === 'function') {
                try {
                    return resolvedPromiseLike<TResult2>(onRejected(reason));
                } catch (e) {
                    return rejectedPromiseLike<TResult2>(e);
                }
            }

            // assume TResult2 == Result and just pass rejection down the chain
            return rejectedPromiseLike(reason) as unknown as PromiseLike<TResult2>;
        },
    };
}

/**
 * Indicates if an object is PromiseLike.
 *
 * @param x anything
 * @returns true if x is PromiseLike; false if not
 */
export function isPromiseLike<T = any>(x: any): x is PromiseLike<T> {
    return typeof x?.then === 'function';
}

/**
 * As Promise.race, but returns sychronously if any of the supplied values resolve/reject
 * synchronously.
 *
 * @param values as Promise.race
 * @returns as Promise.race
 */
export function racesync<T extends readonly unknown[] | []>(
    values: T
): PromiseLike<Awaited<T[number]>> {
    for (const value of values) {
        let settled: PromiseLike<Awaited<T[number]>> | undefined = undefined;

        if (isPromiseLike(value)) {
            value.then(
                (_: any) => {
                    settled = value;
                },
                (_: any) => {
                    settled = value;
                }
            );
        } else {
            settled = resolvedPromiseLike(value as any);
        }

        if (settled !== undefined) {
            return settled;
        }
    }

    return Promise.race(values);
}

/**
 * Polyfill for Promise.withResolvers().
 *
 * @returns { promise, resolve, reject }
 */
export function withResolvers<T>() {
    let resolve: (_: T) => void, reject: (_: any) => void;
    const promise = new Promise<T>((res, rej) => {
        resolve = res;
        reject = rej;
    });

    return { promise, resolve: resolve!, reject: reject! };
}
