export type IErrorWithData<Data> = Error & {
    data: Data;
};

export type IInternalError<Data = undefined> = IErrorWithData<Data> & {
    type: 'internal';
};
export type IUserVisibleError<Data = undefined> = IErrorWithData<Data> & {
    type: 'user-visible';
};

export type CommandError = InternalError | UserVisibleError | Error;

export class InternalError<Data = undefined> extends Error implements IInternalError<Data> {
    type: 'internal' = 'internal';

    constructor(public data: Data) {
        super();
    }
}

export class UserVisibleError<Data = undefined> extends Error implements IUserVisibleError<Data> {
    type: 'user-visible' = 'user-visible';

    constructor(public data: Data) {
        super();
    }
}

export function isUserVisibleError<Data = undefined>(
    error: unknown
): error is IUserVisibleError<Data> {
    return error instanceof Error && 'type' in error && error.type === 'user-visible';
}

export function logError(error: unknown): void {
    if (isUserVisibleError(error)) {
        return;
    }

    console.error('OneStore Command threw an error that we did not expect', error);
}
