import { ArrayIsArray, ObjectEntries } from './language';

function isScalar(value: unknown): value is string | number | boolean | null | undefined {
    return (
        typeof value === 'string' ||
        typeof value === 'number' ||
        typeof value === 'boolean' ||
        value === null ||
        value === undefined
    );
}

function isScalarObject(
    value: object
): value is Record<string, string | number | boolean | null | undefined> {
    return Object.values(value).every((value) => isScalar(value));
}

function isScalarArray(value: any[]): value is (string | number | boolean | null | undefined)[] {
    return value.every((item) => isScalar(item));
}

export function encodeQueryParam(paramName: string, value: unknown, explode: boolean): string[] {
    switch (typeof value) {
        case 'string':
            return [`${paramName}=${encodeURIComponent(value)}`];
        case 'number':
        case 'boolean':
            return [`${paramName}=${value}`];
        case 'object':
            if (value === null) {
                return [];
            }
            if (ArrayIsArray(value)) {
                if (!isScalarArray(value)) {
                    throw new Error(`Unsupported non-scalar array type for ${paramName}`);
                }
                if (explode) {
                    return value.map(
                        (item) => `${paramName}=${item ? encodeURIComponent(item) : item}`
                    );
                }
                return [
                    `${paramName}=${value.map((item) => (item ? encodeURIComponent(item) : item)).join(',')}`,
                ];
            }

            if (!isScalarObject(value)) {
                throw new Error(`Unsupported non-scalar object type for ${paramName}`);
            }

            if (explode) {
                return ObjectEntries(value).map(
                    ([key, value]) => `${key}=${value ? encodeURIComponent(value) : value}`
                );
            }
            return [
                `${paramName}=${ObjectEntries(value)
                    .flat()
                    .map((item) => (item ? encodeURIComponent(item) : item))
                    .join(',')}`,
            ];
        default:
            return [];
    }
}
