export type IncludeExcludeMatcher =
    // exact match
    | string

    // RegExp to match against
    | RegExp

    // predicate function
    | ((s: string) => boolean)

    // array of any of the above
    | Array<IncludeExcludeMatcher>;

export type IncludeExclude = {
    include?: IncludeExcludeMatcher;
    exclude?: IncludeExcludeMatcher;
};

function matches(test: IncludeExcludeMatcher | undefined, s: string): boolean {
    if (test === undefined) {
        return false;
    } else if (typeof test === 'string') {
        return s === test;
    } else if (test instanceof RegExp) {
        return test.test(s);
    } else if (typeof test === 'function') {
        return test(s);
    }

    return test.some((m) => matches(m, s));
}

/**
 * Indicates if an IncludeExclude includes a given string.
 *
 * @param incexc IncludeExclude that specifies strings to be included/excluded
 * @param s string to be checked
 * @returns true in incexc includes s; false if not
 */
export function includes(incexc: IncludeExclude, s: string): boolean {
    // specifically excluded
    if (matches(incexc.exclude, s)) {
        return false;
    }

    // specifically included
    if (matches(incexc.include, s)) {
        return true;
    }

    // include was specified & did not match s, assume excluded
    if (incexc.include) {
        return false;
    }

    // include not specified & not specifically excluded, assume included
    return true;
}
