import { ArrayIsArray, ObjectKeys, ObjectFreeze, WeakSetConstructor } from './language';

const deeplyFrozen = new WeakSetConstructor();

export function deepFreeze(value: any) {
    // No need to freeze primitives or already frozen stuff
    if (typeof value !== 'object' || value === null || deeplyFrozen.has(value)) {
        return;
    }
    deeplyFrozen.add(value);
    if (ArrayIsArray(value)) {
        for (let i = 0, len = value.length; i < len; i += 1) {
            deepFreeze(value[i]);
        }
    } else {
        const keys = ObjectKeys(value);

        for (let i = 0, len = keys.length; i < len; i += 1) {
            deepFreeze(value[keys[i]]);
        }
    }
    ObjectFreeze(value);
}
