import { isResult, type Callback } from '.';
import { ok, err } from './result';
import type { SyncOrAsync } from '.';
import type { Result } from './result';

/**
 * Data that can be subscribed to for changes with a callback.
 */
export type Subscribable<CallbackData, RefreshResult> = {
    subscribe(callback: Callback<CallbackData>): Unsubscribe;
    refresh(): SyncOrAsync<RefreshResult>;
};

export type RefreshResult<E> = Result<void, E>;

export function isSubscribable(obj: unknown): obj is Subscribable<any, any> {
    return (
        typeof obj === 'object' &&
        obj !== null &&
        'subscribe' in obj &&
        typeof obj.subscribe === 'function' &&
        'refresh' in obj &&
        typeof obj.refresh === 'function'
    );
}

export function isSubscribableResult<T, E>(x: unknown): x is SubscribableResult<T, E> {
    if (!isResult(x)) {
        return false;
    }

    return isSubscribable(x.isOk() ? x.value : x.error);
}

export function buildSubscribableResult(
    result: Result<any, any>,
    subscribe: (callback: Callback<Result<any, any>>) => Unsubscribe,
    refresh: () => SyncOrAsync<RefreshResult<any>>
): SubscribableResult<any, any> {
    if (result.isOk()) {
        return ok({ data: result.value, subscribe, refresh });
    } else {
        return err({ failure: result.error, subscribe, refresh });
    }
}

/**
 * Unsubscribe function returned from a subscribe call.
 */
export type Unsubscribe = () => void;

/**
 * Base subscribable type for SubscribableResult to reduce duplication.
 */
type SubscribableBase<T, E> = Subscribable<Result<T, E>, RefreshResult<E>>;

/**
 *  A subscribable result is a Result that allows a consumer to subscribe to changes in the Result. Both success and error cases are subscribable.
 */
export type SubscribableResult<T, E> = Result<
    SubscribableBase<T, E> & { data: T },
    SubscribableBase<T, E> & { failure: E }
>;
