export enum HttpStatusCode {
    Ok = 200,
    Created = 201,
    NoContent = 204,
    NotModified = 304,
    BadRequest = 400,
    Unauthorized = 401,
    Forbidden = 403,
    NotFound = 404,
    ServerError = 500,
    GatewayTimeout = 504,
}

// Logic from https://github.com/salesforce-experience-platform-emu/lds-lightning-platform/blob/main/packages/lds-network-aura/src/middlewares/utils.ts#L197
export function getFetchResponseFromAuraError(err: any): FetchResponse<unknown> {
    // Handle ConnectInJava exception shapes
    if (err.data !== undefined && err.data.statusCode !== undefined) {
        let data: Record<string, any> = {};
        data = err.data as ConnectInJavaError;
        if (err.id !== undefined) {
            data.id = err.id;
        }
        return new FetchResponse(data.statusCode, data);
    }

    // Handle all the other kind of errors
    return new FetchResponse(HttpStatusCode.ServerError, {
        error: err.message,
    });
}

// Backwards-compatible fetch error coerce
// Adapted from https://github.com/salesforce-experience-platform-emu/luvio/blob/main/packages/@conduit-client/network-adapter-fetch/src/fetchNetworkAdapter.ts#L67
export async function coerceResponseToFetchResponse(
    response: Response
): Promise<FetchResponse<unknown>> {
    const { status } = response;
    // coerce headers
    const responseHeaders = {} as any;
    response.headers.forEach((value, key) => {
        responseHeaders[key] = value;
    });

    // parse body
    let responseBody = null;
    if (status !== 204) {
        const contentType = responseHeaders['content-type'];
        responseBody =
            contentType && contentType.startsWith('application/json')
                ? await response.json()
                : await response.text();
    }

    return new FetchResponse(status, responseBody, responseHeaders);
}

export interface ConnectInJavaError {
    data: {
        errorCode: string;
        message: string;
        statusCode: number;
    };
    id: string;
    message: string;
    stackTrace: string;
}

function getStatusText(status: HttpStatusCode): string {
    switch (status) {
        case HttpStatusCode.Ok:
            return 'OK';
        case HttpStatusCode.Created:
            return 'Created';
        case HttpStatusCode.NotModified:
            return 'Not Modified';
        case HttpStatusCode.BadRequest:
            return 'Bad Request';
        case HttpStatusCode.NotFound:
            return 'Not Found';
        case HttpStatusCode.ServerError:
            return 'Server Error';
        default:
            return `Unexpected HTTP Status Code: ${status}`;
    }
}

export interface Headers {
    [name: string]: string;
}

export class FetchResponse<T> extends Error {
    readonly status: HttpStatusCode;
    readonly body: T;
    readonly headers: Headers;
    readonly ok: boolean;
    readonly statusText: string;

    constructor(status: HttpStatusCode, body: T, headers?: Headers) {
        super();
        this.status = status;
        this.body = body;
        this.headers = headers || {};
        this.ok = status >= 200 && this.status <= 299;
        this.statusText = getStatusText(status);
    }
}
